using System;using System.Collections.Generic;using System.Diagnostics;using System.Linq;using System.Threading;
static partial class PartyService {
 static byte[] GroupCommand(byte op,uint id){var bytes=new byte[op==0x1E?2:6];bytes[0]=op;if(bytes.Length==6)Buffer.BlockCopy(BitConverter.GetBytes(id),0,bytes,2,4);return bytes;}
 static PartySnapshot Group(CharacterRef character){using(var memory=Open(character))return memory.ReadParty();}
 static void WaitGroup(Func<bool> condition,CancellationToken token,string failure){var clock=Stopwatch.StartNew();while(clock.ElapsedMilliseconds<6000){token.ThrowIfCancellationRequested();if(condition())return;if(token.WaitHandle.WaitOne(75))token.ThrowIfCancellationRequested();}throw new Exception(failure);}
 static void RequireLeaderAndMembers(CharacterRef leader,IEnumerable<uint> allowed){var state=Group(leader);var ids=new HashSet<uint>(allowed);if(state==null||state.Leader!=leader.Id||state.Members.Any(id=>!ids.Contains(id)))throw new Exception("A composição ou a liderança da PT mudou. Operação interrompida.");}
 public static Outcome Remount(CharacterRef main,CharacterRef[] selected,CancellationToken token,IProgress<string> progress,CharacterRef[] others=null){var result=new Outcome();string phase="verificação inicial";try{
  token.ThrowIfCancellationRequested();if(selected.Length==0)throw new Exception("Selecione os secundários.");var all=new HashSet<uint>(selected.Select(s=>s.Id));if(all.Count!=selected.Length||all.Contains(main.Id))throw new Exception("Seleção de personagens inválida.");all.Add(main.Id);
  var original=Group(main);if(original==null)throw new Exception("O principal está sem PT. Use Montar PT.");if(original.Leader!=main.Id)throw new Exception("O principal precisa ser o líder para remontar PT.");// 0.51.10 (registros 08/11 21:13 dono e 21:17 Esdras: recusava com conta no Mat Farm ou membro de fora na PT): members outside
  // the selection also leave and are invited back at the end — FarmZilla accounts (not marked / in route) accept by the app,
  // anyone else gets the invite and accepts in their own game.
  var extraIds=original.Members.Where(id=>!all.Contains(id)).ToList();var ownExtra=(others??new CharacterRef[0]).Where(o=>extraIds.Contains(o.Id)).GroupBy(o=>o.Id).Select(g=>g.First()).ToList();var outsiders=extraIds.Where(id=>ownExtra.All(o=>o.Id!=id)).ToList();
  if(extraIds.Count>0)progress.Report("Remontar PT: "+extraIds.Count+" membro(s) fora da seleção"+(ownExtra.Count>0?" ("+string.Join(", ",ownExtra.Select(o=>o.Name))+")":"")+" também saem e são convidados de novo"+(outsiders.Count>0?"; quem não está no FarmZilla precisa aceitar o convite no jogo":"")+".");
  var allowed=new HashSet<uint>(all);foreach(var id in extraIds)allowed.Add(id);
  foreach(var secondary in selected){var state=Group(secondary);if(state!=null&&(state.Leader!=main.Id||!original.Members.Contains(secondary.Id)))throw new Exception(secondary.Name+" está em outra PT ou o grupo mudou.");}
  var anchor=selected.FirstOrDefault(s=>original.Members.Contains(s.Id));if(anchor==null)throw new Exception("É necessário um secundário na PT para receber a liderança temporária.");progress.Report("Remontar PT: liderança temporária ficará com "+anchor.Name+".");
  phase="retirada dos demais secundários";
  foreach(var id in extraIds){token.ThrowIfCancellationRequested();RequireLeaderAndMembers(main,allowed);var own=ownExtra.FirstOrDefault(o=>o.Id==id);string label=own!=null?own.Name:"membro "+id;progress.Report("Retirando "+label+" da PT antes de remontar.");Send(main,GroupCommand(0x1F,id),result);WaitGroup(()=>{var state=Group(main);return state!=null&&state.Leader==main.Id&&!state.Members.Contains(id);},token,label+": saída da PT não confirmada.");}
  foreach(var secondary in selected.Where(s=>s.Id!=anchor.Id&&original.Members.Contains(s.Id))){token.ThrowIfCancellationRequested();RequireLeaderAndMembers(main,allowed);progress.Report("Retirando "+secondary.Name+" da PT antes de remontar.");Send(main,GroupCommand(0x1F,secondary.Id),result);WaitGroup(()=>{var state=Group(main);return state!=null&&state.Leader==main.Id&&!state.Members.Contains(secondary.Id)&&Group(secondary)==null;},token,secondary.Name+": saída da PT não confirmada.");}
  phase="transferência de liderança";token.ThrowIfCancellationRequested();RequireLeaderAndMembers(main,new[]{main.Id,anchor.Id});var remaining=Group(main);if(remaining.Members.Count!=2||!remaining.Members.Contains(anchor.Id))throw new Exception("O secundário temporário não está mais na PT.");progress.Report("Passando liderança para "+anchor.Name+".");Send(main,GroupCommand(0x48,anchor.Id),result);
  WaitGroup(()=>{var a=Group(main);var b=Group(anchor);return a!=null&&b!=null&&a.Leader==anchor.Id&&b.Leader==anchor.Id;},token,"Transferência de liderança não confirmada. O principal não foi retirado.");
  phase="saída do principal";token.ThrowIfCancellationRequested();RequireLeaderAndMembers(anchor,new[]{main.Id,anchor.Id});progress.Report(main.Name+": saindo da PT após confirmar a liderança temporária.");Send(main,GroupCommand(0x1E,0),result);WaitGroup(()=>Group(main)==null,token,"Saída do principal não confirmada.");
  phase="liberação do secundário temporário";token.ThrowIfCancellationRequested();WaitGroup(()=>{var state=Group(anchor);return state==null||(state.Leader==anchor.Id&&state.Members.Count==1&&state.Members.Contains(anchor.Id));},token,"O secundário temporário não confirmou a saída dos demais membros.");var anchorParty=Group(anchor);if(anchorParty!=null){if(anchorParty.Leader!=anchor.Id||anchorParty.Members.Count!=1||!anchorParty.Members.Contains(anchor.Id))throw new Exception("A PT temporária recebeu outro membro; não foi desfeita.");Send(anchor,GroupCommand(0x1E,0),result);WaitGroup(()=>Group(anchor)==null,token,"O secundário temporário ainda está em grupo.");}
  phase="novos convites";progress.Report("PT anterior encerrada. Convidando novamente os secundários.");
  foreach(var secondary in selected){token.ThrowIfCancellationRequested();var joined=Join(main,secondary,token,progress);if(joined.Blocked){result.Blocked=true;result.Pid=joined.Pid;throw new Exception(joined.Message);}progress.Report(joined.Message);if(!Together(main,secondary))throw new Exception(secondary.Name+": entrada na nova PT não confirmada.");}
  phase="convites dos membros fora da seleção";
  foreach(var own in ownExtra){token.ThrowIfCancellationRequested();var joined=Join(main,own,token,progress);if(joined.Blocked){result.Blocked=true;result.Pid=joined.Pid;throw new Exception(joined.Message);}progress.Report(joined.Message);}
  foreach(var id in outsiders){token.ThrowIfCancellationRequested();Send(main,GroupCommand(0x1B,id),result);progress.Report("Convite enviado para o membro "+id+" (fora do FarmZilla); ele aceita no jogo dele.");}
  phase="verificação final";var final=Group(main);if(final==null||final.Leader!=main.Id||selected.Any(s=>!Together(main,s)))throw new Exception("A nova PT não foi confirmada em todos os clientes.");result.Message="PT remontada: "+main.Name+" como líder e todos os secundários selecionados confirmados.";
 }catch(OperationCanceledException){result.Message="Remontagem cancelada na etapa: "+phase+". Confira o estado atual da PT.";}catch(Exception e){result.Message="Remontagem interrompida na etapa "+phase+": "+e.Message;}return result;}
}

